package com.proofclean.auth.service;
import com.proofclean.auth.dto.*;import com.proofclean.common.exception.BadRequestException;import com.proofclean.common.exception.UnauthorizedException;import com.proofclean.config.JwtTokenProvider;import com.proofclean.user.entity.*;import com.proofclean.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor
public class AuthService { private final UserRepository userRepository; private final PasswordEncoder passwordEncoder; private final JwtTokenProvider jwtTokenProvider; public AuthResponse register(RegisterRequest r){ if(userRepository.existsByEmail(r.email())) throw new BadRequestException("이미 가입된 이메일입니다."); User u=userRepository.save(User.builder().email(r.email()).password(passwordEncoder.encode(r.password())).name(r.name()).role(Role.USER).build()); return token(u); } public AuthResponse login(LoginRequest r){ User u=userRepository.findByEmail(r.email()).orElseThrow(()->new UnauthorizedException("이메일 또는 비밀번호를 확인하세요.")); if(!passwordEncoder.matches(r.password(), u.getPassword())) throw new UnauthorizedException("이메일 또는 비밀번호를 확인하세요."); return token(u); } private AuthResponse token(User u){ return new AuthResponse(jwtTokenProvider.createToken(u.getEmail()), UserDto.from(u)); } }
